    $bagu_q$[{"url": "/images/02-concurrency/img_007.png", "caption": "图 7：ThreadLocalMap 弱引用 Key 与强引用 Value 内存泄漏引用链示意图"}]$bagu_q$::jsonb, FALSE, TRUE,
