    hints_json = EXCLUDED.hints_json,
    answer_md = EXCLUDED.answer_md,
    images_json = EXCLUDED.images_json,
    has_table = EXCLUDED.has_table,
    has_code = EXCLUDED.has_code,
    sort_order = EXCLUDED.sort_order,
